/*
 * A102259  Begin with 5, multiply each digit by 2, separate the digits.
 * https://oeis.org/A102259
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 105, u16 n <= 105, u32 n <= 105, u64 n <= 105,
 *            u128 n <= 105, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: a(1)=5; for n>1, the sequence is generated by
 * repeatedly reading the next digit from the already generated
 * digits, multiplying it by 2, then appending the decimal digits
 * of the product (in most–significant–digit order) to the end of
 * the sequence, provided those positions have not yet been
 * written.  The nth element of the final infinite sequence is
 * a(n).
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static buffer holding the generated digits */
    static seq_t *buf = NULL;
    static idx_t len = 0;   /* number of digits stored */
    static idx_t cap = 0;   /* allocated capacity of buf */
    static idx_t proc = 0;  /* index of the next digit to consume */

    /* initialise on first call */
    if (buf == NULL) {
        cap = 64;
        buf = (seq_t *)malloc(cap * sizeof(seq_t));
        if (buf == NULL) return (seq_t)0;      /* Out‑of‑memory guard */
        buf[0] = (seq_t)5;   /* a(1) */
        len  = 1;
        proc = 0;
    }

    /* generate until we have at least n digits */
    while (len < n) {
        seq_t d   = buf[proc++];
        seq_t prod = d * (seq_t)2;

        if (prod < (seq_t)10) {
            if (len + 1 > cap) {
                cap <<= 1;
                buf = (seq_t *)realloc(buf, cap * sizeof(seq_t));
                if (buf == NULL) return (seq_t)0;
            }
            buf[len++] = prod;
        } else { /* 10 <= prod <= 18 */
            if (len + 2 > cap) {
                cap <<= 1;
                buf = (seq_t *)realloc(buf, cap * sizeof(seq_t));
                if (buf == NULL) return (seq_t)0;
            }
            buf[len++]     = prod / (seq_t)10; /* most significant digit */
            buf[len++]     = prod % (seq_t)10; /* least significant digit */
        }
    }

    return buf[n - 1];
}
